import ee
ee.Initialize(project='earthsense-436113')

def make_region():
    # Tight union of Punjab and Haryana using two rectangles
    punjab = ee.Geometry.Rectangle([73.7, 29.5, 76.9, 32.6], False)
    haryana = ee.Geometry.Rectangle([74.2, 27.5, 77.7, 30.9], False)
    return punjab.union(haryana, 1)

region = make_region()

DATASETS = [
    ('NASA/VIIRS/002/VNP14A1', 'firemask'),   # primary
    ('NOAA/VIIRS/001/VNP14A1', 'firemask'),   # deprecated fallback
]

def dataset_available(ds, start, end):
    try:
        col = ee.ImageCollection(ds).filterDate(start, end)
        return col.size().getInfo() > 0
    except Exception:
        return False

def pick_dataset():
    test_start = '2024-11-01'
    test_end   = '2024-12-01'
    for ds, method in DATASETS:
        if dataset_available(ds, test_start, test_end):
            return ds, method
    return None, None

def to_fire_binary(img, method):
    if method == 'firemask':
        # FireMask > 1 = active fire (low/nominal/high)
        fm = img.select([b for b in img.bandNames() if b.lower().strip() == 'firemask'].get(0))
        return fm.gt(1).rename('fire').unmask(0).toUint8()
    else:
        return ee.Image(0).rename('fire').toUint8()

def month_counts(col, method, geom, scale=2000):
    # Binary fire per image
    fire_col = col.map(lambda i: to_fire_binary(i, method))
    fire_sum = fire_col.sum().rename('fire')

    # Coverage pixel-days: any valid pixel in any band of original image
    def cov(img):
        m = img.mask().reduce(ee.Reducer.min())
        return ee.Image(1).updateMask(m).toUint8()
    cov_sum = col.map(cov).sum().rename('cov')

    fire_total = fire_sum.reduceRegion(
        reducer=ee.Reducer.sum(),
        geometry=geom,
        scale=scale,
        maxPixels=1e9,
    ).get('fire')

    cov_total = cov_sum.reduceRegion(
        reducer=ee.Reducer.sum(),
        geometry=geom,
        scale=scale,
        maxPixels=1e9,
    ).get('cov')

    return fire_total, cov_total

try:
    geom = region
    ds, method = pick_dataset()
    if ds is None:
        print("Dataset: None")
        print("D")
        raise SystemExit

    print(f"Dataset: {ds}, Method: {method}")

    years = list(range(2012, 2025))
    results = {}
    any_empty = False
    any_no_valid = False
    any_none = False

    for y in years:
        start = ee.Date.fromYMD(y, 11, 1)
        end = ee.Date.fromYMD(y, 12, 1)
        col = ee.ImageCollection(ds).filterDate(start, end)

        n = col.size().getInfo()
        if n == 0:
            print(f"{y} Images: 0")
            any_empty = True
            continue

        fire_total, cov_total = month_counts(col, method, geom, scale=2000)
        fire = fire_total.getInfo()
        cov = cov_total.getInfo()

        if cov is None or cov == 0:
            print(f"{y} Images: {n}, FirePxDays: {fire if fire is not None else 'None'}, CovPxDays: {cov}")
            any_no_valid = True
            continue

        if fire is None:
            print(f"{y} Images: {n}, FirePxDays: None, CovPxDays: {int(cov)}")
            any_none = True
            continue

        results[y] = int(fire)
        print(f"{y} Images: {n}, FirePxDays: {int(fire)}, CovPxDays: {int(cov)}")

    if any_empty:
        print("C1")
        raise SystemExit
    if any_no_valid:
        print("C2")
        raise SystemExit
    if any_none or (results.get(2024, None) is None):
        print("C3")
        raise SystemExit

    past_years = [y for y in years if y < 2024 and y in results]
    if len(past_years) < (2024 - 2012):
        print("C3")
        raise SystemExit

    val_2024 = results[2024]
    min_past = min(results[y] for y in past_years)
    ans = "A" if val_2024 < min_past else "B"
    print(ans)

except Exception as e:
    if str(e).strip() not in ["SystemExit"]:
        print("D")
